import {validateMessage} from './validation.js';

describe('list_sessions frame validation', () => {
  it('accepts a bare frame and forwards valid paging fields without unknown fields', () => {
    expect(validateMessage({type: 'list_sessions'})).toEqual({valid: true, data: {type: 'list_sessions'}});
    expect(
      validateMessage({
        type: 'list_sessions',
        limit: 12,
        before: {sessionId: 'session-1', updatedAt: '2025-01-01T00:00:00.000Z'},
        userId: 'untrusted-user',
      }),
    ).toEqual({
      valid: true,
      data: {
        type: 'list_sessions',
        limit: 12,
        before: {sessionId: 'session-1', updatedAt: '2025-01-01T00:00:00.000Z'},
      },
    });
  });
});
EOF
 timeout 300 npm test -- --runTestsByPath src/transport/ws/listSessionsValidation.test.ts"
